## Code Example
```typescript
interface RateLimiter {
  acquire(key: string, amount: number, ctx?: any): boolean
}
interface RateLimiterFactory {
  create(config: any): RateLimiter
}
class Registry {
  private map = new Map<string, RateLimiterFactory>()
  register(name: string, f: RateLimiterFactory){ this.map.set(name, f) }
  get(name: string, config: any): RateLimiter {
    return this.map.get(name)!.create(config)
  }
}
